using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEditor;using IndianOceanAssets.ShooterSurvival;using Object=UnityEngine.Object;
public static class ValidationRetry19 {static string folder;static int phase,handle,frame;static double at;static List<object> checks;static List<string> errors;static CanvasScript canvas;static Chapter45Director d;static PlayerScript p;static int money;static void Check(bool pass,string label){checks.Add(new{pass,label});if(!pass)throw new Exception(label);}static string Json(object o)=>(string)AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{o});static void Bind(){canvas=Object.FindFirstObjectByType<CanvasScript>();d=Object.FindFirstObjectByType<Chapter45Director>();p=Object.FindFirstObjectByType<PlayerScript>();}static void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m);}
 public static object Main(string output){if(!EditorApplication.isPlaying)throw new Exception("Fresh Play only");folder=output;Directory.CreateDirectory(folder);checks=new();errors=new();phase=frame=0;at=EditorApplication.timeSinceStartup;Bind();Check(d!=null&&!d.Running&&d.Elapsed==0,"Fresh new-game lobby before Start");money=MoneyScript.S.Jewel;canvas.PlayerPressedStartButton();Application.logMessageReceived+=Log;EditorApplication.update+=Tick;return new{started=true};}
 static void Tick(){if(frame==Time.frameCount)return;frame=Time.frameCount;try{double age=EditorApplication.timeSinceStartup-at;if(age>80)throw new Exception("Retry timeout");if(phase==0){if(!d.Running||d.Elapsed<10)return;Check(p.currentHealth>0&&d.Distance>0,"Ordinary Start advances native route");ScreenCapture.CaptureScreenshot(Path.Combine(folder,"before-retry.png"));canvas.PauseGame();handle=SceneManager.GetActiveScene().handle;var button=canvas.transform.Find("SettingsMenu/Panel/RunActions/Retry").GetComponent<Button>();Check(button.isActiveAndEnabled&&button.interactable,"Native Retry button available");phase=1;button.onClick.Invoke();return;}if(phase==1){if(SceneManager.GetActiveScene().handle==handle)return;Bind();if(d==null||canvas==null||p==null)return;if((bool)typeof(CanvasScript).GetField("reloadInputSuppressed",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null))return;Check(!d.Running&&d.Elapsed==0&&d.LiftCount==0&&!d.GoalClaimed,"Native Retry resets route clocks, lift count and goal");Check(Object.FindObjectsByType<BulletScript>(FindObjectsSortMode.None).Count(b=>b.gameObject.activeInHierarchy)==0,"Retry lobby has no stale active bullets");Check(MoneyScript.S.Jewel==money,"Retry does not award a chapter clear");Check(d.encounters.All(e=>!e.Complete&&!e.Activated),"Retry resets all encounters");canvas.PlayerPressedStartButton();phase=2;return;}if(phase==2&&d.Running&&d.Elapsed>5){Check(p.currentHealth>0&&d.Distance>0,"Native Start works after Retry");ScreenCapture.CaptureScreenshot(Path.Combine(folder,"after-retry.png"));phase=3;at=EditorApplication.timeSinceStartup;return;}if(phase==3&&age>1)Finish(null);}catch(Exception e){Finish(e.ToString());}}
 static void Finish(string error){EditorApplication.update-=Tick;Application.logMessageReceived-=Log;File.WriteAllText(Path.Combine(folder,"result.json"),Json(new{completed=error==null,error,checks,errors,ordinaryStats=true,healthOrPositionOverrides=false,retry="Existing SettingsMenu Retry button UnityEvent"}));}
}
